import 'dart:async';

import 'package:flutter/material.dart';
import 'package:flutter_riverpod/flutter_riverpod.dart';

import '../../notifications/notification_feed_entry_card.dart';
import '../../providers/global/shopin_bit_service_provider.dart';
import '../../providers/ui/notification_feed_provider.dart';
import '../../services/shopinbit/shopinbit_service.dart';
import '../../themes/stack_colors.dart';
import '../../utilities/text_styles.dart';
import '../../widgets/background.dart';
import '../../widgets/custom_buttons/app_bar_icon_button.dart';
import '../../widgets/rounded_white_container.dart';

class NotificationsView extends ConsumerStatefulWidget {
  const NotificationsView({super.key, this.walletId});

  final String? walletId;

  static const routeName = "/notifications";

  @override
  ConsumerState<NotificationsView> createState() => _NotificationsViewState();
}

class _NotificationsViewState extends ConsumerState<NotificationsView> {
  late final ShopInBitService _shopInBitService;

  @override
  void initState() {
    super.initState();
    _shopInBitService = ref.read(pShopinBitService);
  }

  @override
  void dispose() {
    if (widget.walletId == null) {
      unawaited(_shopInBitService.markAllNotificationsRead());
    }
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    final entries = ref.watch(pNotificationFeed(widget.walletId));

    return Background(
      child: Scaffold(
        backgroundColor: Theme.of(context).extension<StackColors>()!.background,
        appBar: AppBar(
          title: Text("Notifications", style: STextStyles.navBarTitle(context)),
          leading: AppBarBackButton(
            onPressed: () async {
              Navigator.of(context).pop();
            },
          ),
        ),
        body: SafeArea(
          child: Padding(
            padding: const EdgeInsets.all(12),
            child: entries.isNotEmpty
                ? Column(
                    children: [
                      Expanded(
                        child: ListView.builder(
                          shrinkWrap: true,
                          itemCount: entries.length,
                          itemBuilder: (builderContext, index) {
                            return Padding(
                              padding: const EdgeInsets.all(4),
                              child: NotificationFeedEntryCard(
                                entry: entries[index],
                              ),
                            );
                          },
                        ),
                      ),
                    ],
                  )
                : Column(
                    crossAxisAlignment: CrossAxisAlignment.center,
                    children: [
                      Padding(
                        padding: const EdgeInsets.all(4),
                        child: RoundedWhiteContainer(
                          child: Center(
                            child: FittedBox(
                              fit: BoxFit.scaleDown,
                              child: Text(
                                "Notifications will appear here",
                                style: STextStyles.itemSubtitle(context),
                              ),
                            ),
                          ),
                        ),
                      ),
                    ],
                  ),
          ),
        ),
      ),
    );
  }
}
